def norm(cells):
    rs=[a for a,b in cells]; cs=[b for a,b in cells]
    mnr,mnc=min(rs),min(cs)
    s=frozenset((a-mnr,b-mnc) for a,b in cells)
    return s
def variants(s):
    out=set()
    cur=s
    for _ in range(4):
        out.add(cur)
        out.add(frozenset((a,-b) for a,b in cur))
        cur=frozenset((b,-a) for a,b in cur)  # rotate
    return out
