def comps_of(g,conn=8):
    import collections
    bg=collections.Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=set(); out=[]
    H,W=len(g),len(g[0])
    nb=[(da,db) for da in(-1,0,1) for db in(-1,0,1) if (da,db)!=(0,0) and (conn==8 or abs(da)+abs(db)==1)]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in nb:
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]!=bg:
                            seen.add((x,y)); st.append((x,y))
                out.append(cells)
    return bg,out
def mindist(c1,c2):
    return min(abs(a-x)+abs(b-y) for a,b in c1 for x,y in c2)

def predict(g):
    bg,C=comps_of(g,8)
    infos=[]
    for c in C:
        cols=set(g[a][b] for a,b in c)
        infos.append({'cells':c,'cols':cols,'maj':max(cols,key=lambda k:sum(1 for a,b in c if g[a][b]==k)),'n':len(c),'shape':norm(c),'col':g[c[0][0]][c[0][1]]})
    from collections import Counter
    ccomp=Counter(d['col'] for d in infos)
    out=[row[:] for row in g]
    changes=[]
    # multi-color comps: foreign cells -> majority, but only if foreign color occupies 1 cell? test both variants later
    for d in infos:
        if len(d['cols'])>1:
            for a,b in d['cells']:
                if g[a][b]!=d['maj']: changes.append((a,b,d['maj'],'multi'))
    # pairs
    pairs=[]
    for i,a in enumerate(infos):
        for j in range(i+1,len(infos)):
            b=infos[j]
            if a['col']!=b['col'] and a['n']==b['n'] and a['shape'] in variants(b['shape']):
                pairs.append((a,b))
    if pairs:
        a,b=max(pairs,key=lambda p:max(p[0]['n'],p[1]['n']))
        # target: largest comp with singleton color, excluding a,b colors
        cand=[d for d in infos if ccomp[d['col']]==1 and d['col'] not in (a['col'],b['col'])]
        tgt=max(cand,key=lambda d:d['n'])['col']
        # corrupted = farther from target comp
        tgtcomp=[d for d in infos if d['col']==tgt][0]
        da=db=mindist(a['cells'],tgtcomp['cells']); 
        da=mindist(a['cells'],tgtcomp['cells']); db=mindist(b['cells'],tgtcomp['cells'])
        bad = a if da>db else b
        for x,y in bad['cells']: changes.append((x,y,tgt,'pair'))
    for x,y,c,_ in changes: out[x][y]=c
    return out,changes,bg

