def units(g):
    H,W=len(g),len(g[0]); seen=set(); us=[]
    for i in range(H):
        for j in range(W):
            if (i,j) not in seen and g[i][j]!=None:
                col=g[i][j]; st=[(i,j)]; seen.add((i,j)); grp=[]
                while st:
                    a,b=st.pop(); grp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]==col:
                                seen.add((x,y)); st.append((x,y))
                us.append(grp)
    return us

def predict3(g):
    us=[{'cells':c,'n':len(c),'col':g[c[0][0]][c[0][1]],'shape':norm(c)} for c in units(g)]
    out=[r[:] for r in g]; changes=[]
    from collections import Counter
    cu=Counter(d['col'] for d in us)
    # stray: single-cell unit adjacent to a larger unit, and its color has another unit elsewhere
    for d in us:
        if d['n']==1 and cu[d['col']]>1:
            (x,y),=d['cells']
            adj=[e for e in us if e['n']>1 and any(abs(x-a)<=1 and abs(y-b)<=1 for a,b in e['cells'])]
            if adj:
                B=max(adj,key=lambda e:e['n'])
                changes.append((x,y,B['col'],'stray')); out[x][y]=B['col']
    if not changes:
        pairs=[]
        for i,a in enumerate(us):
            for j in range(i+1,len(us)):
                b=us[j]
                if a['col']!=b['col'] and a['n']==b['n'] and a['shape'] in variants(b['shape']):
                    pairs.append((a,b))
        if pairs:
            a,b=max(pairs,key=lambda p:p[0]['n'])
            cand=[d for d in us if cu[d['col']]==1 and d['col'] not in (a['col'],b['col'])]
            tgt=max(cand,key=lambda d:d['n'])['col']
            tc=[d for d in us if d['col']==tgt][0]
            bad=a if mindist(a['cells'],tc['cells'])>mindist(b['cells'],tc['cells']) else b
            for x,y in bad['cells']: changes.append((x,y,tgt,'pair')); out[x][y]=tgt
    return out,changes

