def units(g):
    from collections import Counter as Ct2
    bg=Ct2(x for r in g for x in r).most_common(1)[0][0]
    H,W=len(g),len(g[0]); seen=set(); us=[]
    for i in range(H):
        for j in range(W):
            if (i,j) not in seen and g[i][j]!=bg:
                col=g[i][j]; st=[(i,j)]; seen.add((i,j)); grp=[]
                while st:
                    a,b=st.pop(); grp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]==col:
                                seen.add((x,y)); st.append((x,y))
                us.append(grp)
    return us,bg

