import itertools, functools

def comps(g, conn=8):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if seen[r][c] or g[r][c]==None: continue
            col=g[r][c]; stack=[(r,c)]; seen[r][c]=True; cells=[]
            while stack:
                a,b=stack.pop(); cells.append((a,b))
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        if dr==0 and dc==0: continue
                        if conn==4 and dr!=0 and dc!=0: continue
                        nr,nc=a+dr,b+dc
                        if 0<=nr<R and 0<=nc<C and not seen[nr][nc] and g[nr][nc]==col:
                            seen[nr][nc]=True; stack.append((nr,nc))
            out.append(cells)
    return out

def normset(u):
    mr=min(r for r,c in u); mc=min(c for r,c in u)
    return frozenset((r-mr,c-mc) for r,c in u)

def analyze(g, conn):
    cs=comps(g,conn)
    cnt=Counter(g[r][c] for r in range(len(g)) for c in range(len(g[0])))
    bg=cnt.most_common(1)[0][0]
    return cs,bg

