            if len(cols[col])<2 or col==bg: continue
            (r,c),=u
            adj=[(din[a][b],) for a in range(r-1,r+2) for b in range(c-1,c+2)
                 if (a,b)!=(r,c) and 0<=a<len(din) and 0<=b<len(din[0]) and din[a][b]!=col and din[a][b]!=bg and din[a][b] is not None]
            adj=[x[0] for x in adj]
            if adj:
                # adjacent colors sorted by unit size desc
                cand=sorted(set(adj), key=lambda cc: -max(len(uu) for uu in cols[cc]))
                return (u,cand[0]),'stray'
    # pairs
    ps=[]
    for (cA,uA),(cB,uB) in itertools.combinations(cols.items(),2):
