    def transform(din):
        R,C=len(din),len(din[0])
        bg=Counter(v for r in din for v in r).most_common(1)[0][0]
        seen=set(); us=[]
        for r in range(R):
            for c in range(C):
                if din[r][c]!=bg and (r,c) not in seen:
                    col=din[r][c]; st=[(r,c)]; seen.add((r,c)); comp=[]
                    while st:
                        a,b=st.pop(); comp.append((a,b))
                        for dr in range(-1,2):
                            for dc in range(-1,2):
                                if dr==0 and dc==0: continue
                                if conn==4 and dr and dc: continue
                                x,y=a+dr,b+dc
                                if 0<=x<R and 0<=y<C and (x,y) not in seen and din[x][y]==col:
                                    seen.add((x,y)); st.append((x,y))
                    us.append((col,comp))
        cols=defaultdict(list)
        for col,comp in us: cols[col].append(comp)
        def mdist(u,t): return min(abs(r-tr)+abs(c-tc) for (r,c) in u for (tr,tc) in t)
        def cheb(u,t): return min(max(abs(r-tr),abs(c-tc)) for (r,c) in u for (tr,tc) in t)
        M={'md':mdist,'cheb':cheb}[metric]
        # stray single absorbed by neighboring larger unit of another color
        if stray_on:
            for u in sorted(us,key=lambda cu:-len(cu[1])):
                col,comp=u
                if len(comp)!=1 or col==bg or len(cols[col])>1: continue
                (r,c),=comp
                adj={din[a][b] for a in range(max(0,r-1),min(R,r+2)) for b in range(max(0,c-1),min(C,c+2))
                     if din[a][b] not in (col,bg)}
                if adj:
                    cand=sorted(adj,key=lambda cc:-max(len(uu) for uu in cols[cc]))
                    tgt=cand[0]
                    g=[row[:] for row in din]; g[r][c]=tgt; return g
        def norm(cells):
            r0=min(r for r,c in cells); c0=min(c for r,c in cells)
            return tuple(sorted((r-r0,c-c0) for r,c in cells))
        cls=defaultdict(list)
        for col,comp in us:
            if len(comp)>=(1 if size1 else 2): cls[norm(comp)].append((col,comp))
        ps=[(col,comp) for v in cls.values() if len(v)>=2 for col,comp in v]
        if not ps: return [row[:] for row in din]
        # target: largest unit among single-unit colors, excluding candidate colors
        cnt=Counter(col for col,_ in us)
        candt=[(len(comp),col,comp) for col,comp in us if cnt[col]==1 and col not in {c for c,_ in ps}]
        if not candt: return [row[:] for row in din]
